INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷134·僭伪列传·李昪", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/184c40b49cc874d45b3c000680968fee2ef8f443/content/books/zizhi-tongjian/vol-281/year-0937/part-07/sources/library/jiuwudaishi-134-accession/source.txt", "note": "《旧五代史》卷134·僭伪列传·李昪，段落 jiu-wudaishi-205deb4a7860-p003204；已核上下文及传主，纸本及异文待核。", "id": "910988dc-e45c-532a-b172-769b00ffaf89"}, {"title": "资治通鉴·后晋纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/184c40b49cc874d45b3c000680968fee2ef8f443/content/books/zizhi-tongjian/vol-281/year-0937/part-07/sources/library/tongjian-281-937-min-and-year-end/source.txt", "note": "《资治通鉴》后晋纪二，段落 zizhi-tongjian-a63549944a71-p003344；电子底本待考，分段待核", "id": "d8d1c4ee-12e0-529e-9179-322c7c7670a8"}, {"title": "新五代史·卷62·南唐世家", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/184c40b49cc874d45b3c000680968fee2ef8f443/content/books/zizhi-tongjian/vol-281/year-0937/part-07/sources/library/xinwudaishi-062-accession/source.txt", "note": "《新五代史》卷62·南唐世家，段落 xin-wudaishi-b08f244b9241-p003128；已核上下文及传主，纸本及异文待核。", "id": "fa6cfc9d-507c-5fa2-9e84-890a60000798"}, {"title": "新五代史·卷68·闽世家", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/184c40b49cc874d45b3c000680968fee2ef8f443/content/books/zizhi-tongjian/vol-281/year-0937/part-07/sources/library/xinwudaishi-068-wang-jigong/source.txt", "note": "《新五代史》卷68·闽世家，段落 xin-wudaishi-b08f244b9241-p003403；已核上下文及传主，纸本及异文待核。", "id": "1cff965f-51a4-57d6-a520-e24910cb4bd9"}, {"title": "资治通鉴·后晋纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/7ab11539b383300ef1f618b97db115f4d85186a1/content/books/zizhi-tongjian/vol-281/year-0937/part-05/sources/library/tongjian-281-937-july-aftermath/source.txt", "note": "《资治通鉴》后晋纪二，段落 zizhi-tongjian-a63549944a71-p003343；电子底本待考，分段待核", "id": "cc007ffa-0d92-56e5-9c30-c70f558d191c"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "杨溥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷270贞明五年条所见人物：杨溥。", "biography": null, "status": "draft", "id": "c9c313a8-8feb-5442-a006-67b9f78d476b"}, {"name": "杨璘", "aliases": ["楊璘"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成三年条所见人物：杨璘，获封江夏王者。", "biography": null, "status": "draft", "id": "d9403d90-88ab-5ee1-acc2-2c049b3f8b54"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "徐温", "aliases": ["徐溫"], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“张颢、徐温发动兵谏，控制淮南军政”中为事变组织者。", "biography": null, "status": "draft", "id": "d3682e36-8a8e-5558-8399-51a71c81330f"}, {"name": "徐玠", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：徐玠。", "biography": null, "status": "draft", "id": "70906153-ef05-55ab-b89f-58cf163dfda3"}, {"name": "徐知证", "aliases": ["徐知證"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐氏宗室。937年十月，徐诰即位后封他为江王。《新五代史》也记载这一封爵。", "biography": null, "status": "draft", "id": "4343d028-faf4-51b1-a2ef-c11390e12a40"}, {"name": "徐知谔", "aliases": ["徐知諤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：徐知谔，润州团练使、被叙亲自交易者。", "biography": null, "status": "draft", "id": "ac076e03-0802-5e0f-9c3f-c1a717712543"}, {"name": "杨琏", "aliases": ["楊璉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成三年条所见人物：杨琏，获封江都王者。", "biography": null, "status": "draft", "id": "4975dc84-c87f-5d7f-b1e7-3254e45440ea"}, {"name": "李德诚", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷258龙纪元年条所见人物：李德诚。", "biography": null, "status": "draft", "id": "59a78323-0271-515f-9eee-806a51a30252"}, {"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "杨珙", "aliases": ["楊珙"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷276天成二年条所见人物：杨珙，获封建安王者。", "biography": null, "status": "draft", "id": "36891e7d-cbab-5a6a-87ef-52ca0cefa3a5"}, {"name": "张延翰", "aliases": ["張延翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴国、南唐官员。原任吴国同平章事，937年十月与张居咏、李建勋一同被任命为南唐同平章事。", "biography": null, "status": "draft", "id": "51662122-1d02-5d49-9bbc-a0324cabb6ff"}, {"name": "张居咏", "aliases": ["張居詠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "吴国、南唐官员。原任吴国门下侍郎，937年十月与张延翰、李建勋一同被任命为南唐同平章事。", "biography": null, "status": "draft", "id": "64cde81e-02cc-52fd-9160-264f97bd9900"}, {"name": "李建勋", "aliases": ["李建勳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李建勋，节度副使、屡陈功业者。", "biography": null, "status": "draft", "id": "6b23676b-32be-5201-8ad3-171b7cc648e3"}, {"name": "齐王妃（徐知诰妻）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "徐知诰担任齐王时的王妃。937年在吴国册命齐王的记载中被册为王后；此段没有记载她的姓名。", "biography": null, "status": "draft", "id": "331ce8de-2b94-5acb-8d2b-ff60acb0fd25"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "王继鹏", "aliases": ["王繼鵬", "王昶"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王继鹏，被任命权军府事的王子。", "biography": null, "status": "draft", "id": "94e0308c-1642-5beb-9233-76f848fff4f0"}, {"name": "王继恭", "aliases": ["王繼恭"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国官员，937年以威武节度使身份奉闽王命向后晋报告继位并请求设立邸舍。《资治通鉴》称他为闽王王继鹏的弟弟，《新五代史》称为儿子，亲属身份存在异说。", "biography": null, "status": "draft", "id": "10a53d6a-e6d8-5230-b1aa-76b1340b24f1"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "杨溥命杨璘将皇帝玺绶奉送齐国", "start_year": 937, "end_year": 937, "time_original": "937年九月丙寅", "dynasty": "五代十国", "description": "杨溥命杨璘将皇帝玺绶奉送齐国。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "db875e64-d2b9-58cb-a4ab-c5ae10035873"}, {"title": "徐诰在金陵即皇帝位并大赦、改元升元", "start_year": 937, "end_year": 937, "time_original": "937年十月甲申", "dynasty": "五代十国", "description": "徐诰在金陵即皇帝位，宣布大赦，改元升元。《资治通鉴》此处写国号唐；新旧《五代史》写初号齐，国号的时间记载存在差异。", "phases": [], "location_name": "金陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a42224bb-bd58-5a91-961f-ca376b1be3dc"}, {"title": "徐诰追尊徐温为武皇帝", "start_year": 937, "end_year": 937, "time_original": "937年十月甲申即位后", "dynasty": "五代十国", "description": "徐诰追尊徐温为武皇帝。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "06caec4d-95e0-5a1d-a51c-79404f54d296"}, {"title": "徐诰派徐玠奉册尊杨溥为让皇", "start_year": 937, "end_year": 937, "time_original": "937年十月乙酉", "dynasty": "五代十国", "description": "徐诰派徐玠奉册尊杨溥为让皇。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "80eef20e-a442-5215-8720-8f93d30686dd"}, {"title": "徐诰保留杨溥的生活礼遇，并沿用吴国礼制", "start_year": 937, "end_year": 937, "time_original": "937年十月乙酉册尊条下", "dynasty": "五代十国", "description": "杨溥的宫室、乘舆和服用待遇保持原样。宗庙、历法正朔、徽章和服色仍依吴国制度。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2fb11234-fa35-5af8-8c52-4dd741ca7ea9"}, {"title": "徐知证被封为江王", "start_year": 937, "end_year": 937, "time_original": "937年十月丁亥", "dynasty": "五代十国", "description": "徐知证被封为江王。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ea6ab153-9632-5253-a16b-d0121c2ebed8"}, {"title": "徐知谔被封为饶王", "start_year": 937, "end_year": 937, "time_original": "937年十月丁亥", "dynasty": "五代十国", "description": "徐知谔被封为饶王。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "fc419af3-27c9-5da0-b155-f2d3747f36aa"}, {"title": "杨琏领平卢节度使、兼中书令并封弘农公", "start_year": 937, "end_year": 937, "time_original": "937年十月丁亥封爵条下", "dynasty": "五代十国", "description": "杨琏领平卢节度使、兼中书令并封弘农公。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6b0f5bb4-b550-56b8-8264-1b967b90132e"}, {"title": "李德诚在天泉阁宴会上出示宋齐丘阻止劝进的书信", "start_year": 937, "end_year": 937, "time_original": "937年十月，具体日期未记载", "dynasty": "五代十国", "description": "徐诰宴请群臣时，李德诚称只有宋齐丘对即位不满，并出示宋齐丘阻止自己劝进的信。徐诰拿着信没有看，表示相信三十年的旧交宋齐丘；宋齐丘叩头谢罪。", "phases": [], "location_name": "天泉阁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "50c21426-0bd3-5ffd-b3b8-f41461040f66"}, {"title": "徐诰上表杨溥，更改东都宫殿名为仙经中的名称", "start_year": 937, "end_year": 937, "time_original": "937年十月己丑", "dynasty": "五代十国", "description": "徐诰上表杨溥，更改东都宫殿名为仙经中的名称。", "phases": [], "location_name": "东都（江都）", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "615c6268-0596-575e-a8bb-270e84e101fe"}, {"title": "杨溥常穿羽衣，练习辟谷", "start_year": null, "end_year": null, "time_original": "受禅后的生活记载，具体起止日期未载", "dynasty": "五代十国", "description": "杨溥退位后常穿羽衣，并练习辟谷，也就是以减少或停止谷物摄入为特点的道教修习。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1a77074b-a5c2-545e-beda-271bbf5347e9"}, {"title": "杨珙等十二名吴国宗室降爵为公，同时加官增邑", "start_year": 937, "end_year": 937, "time_original": "937年十月辛卯", "dynasty": "五代十国", "description": "杨珙等十二名吴国宗室降爵为公，同时加官增邑。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "297c19c3-0689-5555-a8a2-5f76ab3cf532"}, {"title": "张延翰、张居咏、李建勋被任命为南唐同平章事", "start_year": 937, "end_year": 937, "time_original": "937年十月丙申", "dynasty": "五代十国", "description": "徐诰任命原吴国同平章事张延翰、门下侍郎张居咏和中书侍郎李建勋为南唐同平章事。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "895223fd-5284-5dde-adce-2d5d8b2dfaef"}, {"title": "杨溥写信辞谢徐诰继续向自己上表，徐诰未改变做法", "start_year": 937, "end_year": 937, "time_original": "937年十月受禅后的交往，具体日期未记载", "dynasty": "五代十国", "description": "杨溥写信辞谢徐诰继续向自己上表，徐诰未改变做法。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "344685e3-e962-5a40-b3c3-49c53e41bb27"}, {"title": "宋齐丘被加授大司徒", "start_year": 937, "end_year": 937, "time_original": "937年十月丁酉", "dynasty": "五代十国", "description": "宋齐丘被加授大司徒。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4c061b7d-ed14-5551-91c5-a3698355b46e"}, {"title": "宋齐丘因未参与政事和诏词提及布衣旧交而表达不满", "start_year": 937, "end_year": 937, "time_original": "937年十月丁酉加授大司徒条下", "dynasty": "五代十国", "description": "宋齐丘虽任左丞相，却不参与政事。他因诏词提到“布衣之交”而大声表示，自己还是布衣时徐诰只是刺史，如今徐诰成为天子，便可以不用自己了。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9f75ad0a-67fd-5d6f-a376-410d0fb19baf"}, {"title": "宋齐丘回家请罪，徐诰亲笔诏书致歉但没有改命", "start_year": 937, "end_year": 937, "time_original": "937年十月丁酉加授引发争执之后", "dynasty": "五代十国", "description": "宋齐丘回家请罪，徐诰亲笔诏书致歉但没有改命。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d3b2064a-9adc-5bc5-8b64-98b331021a3e"}, {"title": "宋齐丘建议迁走杨溥、疏远杨琏并断绝婚姻，徐诰拒绝", "start_year": null, "end_year": null, "time_original": "十月争执之后久之，具体年月未载", "dynasty": "五代十国", "description": "过了一段时间，宋齐丘又上书建议把杨溥迁到其他州，疏远吴国旧太子杨琏，并断绝他的婚姻。徐诰没有采纳。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "82d1318a-91b6-5226-a07d-d9a997182156"}, {"title": "徐诰立王后宋氏为皇后", "start_year": 937, "end_year": 937, "time_original": "937年十月乙巳", "dynasty": "五代十国", "description": "徐诰立王后宋氏为皇后。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "84aafb96-ff5c-5d92-b36e-b1d043ee12c8"}, {"title": "徐景通被任命为诸道副元帅等职并封吴王", "start_year": 937, "end_year": 937, "time_original": "937年十月戊申", "dynasty": "五代十国", "description": "徐诰将原任诸道都统、判元帅府事的徐景通任命为诸道副元帅、判六军诸卫事、太尉、尚书令，并封吴王。徐景通与后来的李璟是同一人。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "63c68ec9-538e-5421-9236-6c3edf219012"}, {"title": "王继鹏命王继恭向后晋报告继位，并请求设邸舍", "start_year": 937, "end_year": 937, "time_original": "937年十月，具体日期未记载", "dynasty": "五代十国", "description": "王继鹏命威武节度使王继恭向后晋上表，报告自己的继位，并请求在后晋都城设立邸舍。《资治通鉴》称王继恭为其弟，《新五代史》称为其子，亲属身份待进一步校核。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "719f0004-ba45-5099-8e34-74d03b34febc"}]'::jsonb)
